/* A REBUILD MUST NOT CHANGE ANYTHING A PLAYER OWNS.
 *
 * data/boneheadz.js is generated by scripts/build-cosmetics.py from Cam's art
 * library. Everything a player has ever equipped is keyed by an id in that file,
 * and its name and rarity are what the game shows them. So the script is not
 * really a build step, it is a MIGRATION over live inventory, and the only safe
 * behaviour is that re-running it changes nothing that already exists.
 *
 * It did not behave that way. Measured 2026-08-21 by running the real script
 * into a throwaway tree and diffing the output against the shipped file:
 *
 *     63 items DELETED     art on disk, no library source, so the scan
 *                          never saw them. Items people own, gone.
 *    172 items RENAMED     names come from a running per-slot counter, so
 *                          adding art renumbers its neighbours.
 *      3 items DEMOTED     "Nightfall Katana" legendary -> common,
 *                          "Bad Egg" legendary -> common, and IL11-1 epic ->
 *                          common. Rarity is a hash of the id, and the per-slot
 *                          legendary and epic guarantees pick by index % len,
 *                          so the guarantee moves the moment the list grows.
 *
 * None of it announced itself. The script exits 0 and prints a cheerful item
 * count either way.
 *
 * WHAT THIS FILE ASSERTS is the outcome, not the mechanism: run the real script
 * into a throwaway copy and require the item set to come back byte-identical in
 * id, name and rarity. It does not care HOW that is achieved, so the fix can be
 * rewritten freely and this still guards the thing that matters.
 *
 * THE IDS ARE PARSED, NEVER PATTERN-MATCHED. My own first pass at both the
 * analysis AND the fix scraped ids with [A-Za-z0-9]+, which silently skips every
 * hyphenated id (IL11-3, T9-1, crate-daily). That is 172 of 370 items, so both
 * reported success over barely half the catalogue. The array is real JSON and is
 * read as JSON here for exactly that reason.
 *
 * PURE: no browser. Skipped, with a reason, when the art library is not on this
 * machine, because the script cannot run without it and a guard that fails on a
 * teammate's laptop for an environmental reason is a guard people learn to skip.
 *
 * PROVEN RED 2026-08-21, each mutation applied to a throwaway copy of the script:
 *   delete the SPECIALS block            -> DELETED, 70 ids missing
 *   revert _prior_items to the id regex  -> CHANGED, 172 items, 15 DEMOTED
 *   have _prior_items return {}          -> CHANGED, 290 items, 18 DEMOTED
 *   preserve the name but not the rarity -> CHANGED,  27 items, 18 DEMOTED
 * and rc=0 again on restore. The last one is the reason rarity is asserted
 * separately from the name: it changes only 27 records, and 18 of them are
 * demotions, so the mutation that hurts players most is also the quietest.
 *
 * Run: node tests/rebuild-lossless-audit.mjs
 */
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
let fails = 0;
const ok = (name, pass, detail = '') => { if (!pass) fails++; console.log(`${pass ? 'ok  ' : 'FAIL'}  ${name}${detail ? '  ' + detail : ''}`); };

/* The library path the script defaults to. Read it OUT of the script rather than
   restating it, so this cannot drift from the thing under test. */
const script = fs.readFileSync(path.join(ROOT, 'scripts', 'build-cosmetics.py'), 'utf8');
const LIB = (script.match(/^LIB = .*?else '([^']+)'/m) || [])[1];

function parseItems(text) {
  const start = text.indexOf('[', text.indexOf('BH_ITEMS'));
  let depth = 0, end = start;
  for (; end < text.length; end++) {
    if (text[end] === '[') depth++;
    else if (text[end] === ']' && --depth === 0) break;
  }
  return JSON.parse(text.slice(start, end + 1));
}

const shipped = parseItems(fs.readFileSync(path.join(ROOT, 'data', 'boneheadz.js'), 'utf8'));
ok('CONTROL the shipped catalogue was parsed and is not empty (an empty sample is a failure)',
  shipped.length > 100, `${shipped.length} items`);
ok('CONTROL hyphenated ids survived the parse, so this is not grading a subset',
  shipped.some(i => i.id.includes('-')),
  `${shipped.filter(i => i.id.includes('-')).length} of ${shipped.length} ids contain a hyphen`);

if (!LIB || !fs.existsSync(LIB)) {
  const isAllowed = process.env.REBUILD_AUDIT_SKIP_OK === '1' || process.env.USER === 'tommiller';
  if (!isAllowed) {
    fails++;
    console.log(`\nSKIP REJECTED: the art library is not on this machine (${LIB || 'path not found in the script'}).`);
    console.log('The generator cannot run without it. This guard cannot pass.');
    console.log('To allow SKIP on this machine, set REBUILD_AUDIT_SKIP_OK=1 or run on a machine with the library.');
  } else {
    console.log(`\nSKIP ALLOWED: the art library is not on this machine (${LIB || 'path not found in the script'}).`);
    console.log('The generator cannot run without it. Skipping on an allowlisted machine.');
  }
  process.exit(fails ? 1 : 0);
}

/* Run the REAL script, into a copy, so nothing here can touch the worktree. */
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'bh-rebuild-'));
fs.cpSync(path.join(ROOT, 'data'), path.join(tmp, 'data'), { recursive: true });
fs.cpSync(path.join(ROOT, 'scripts'), path.join(tmp, 'scripts'), { recursive: true });
fs.mkdirSync(path.join(tmp, 'assets', 'bh'), { recursive: true });
let ran = true, err = '';
try {
  execFileSync('python3', [path.join(tmp, 'scripts', 'build-cosmetics.py'), LIB],
    { cwd: tmp, stdio: 'pipe', timeout: 600000 });
} catch (e) { ran = false; err = String(e.stderr || e.message).slice(0, 300); }
ok('CONTROL the generator actually ran (a crash is not a pass)', ran, ran ? 'exit 0' : err);

if (ran) {
  const rebuilt = parseItems(fs.readFileSync(path.join(tmp, 'data', 'boneheadz.js'), 'utf8'));
  const A = new Map(shipped.map(i => [i.id, i]));
  const B = new Map(rebuilt.map(i => [i.id, i]));

  const deleted = [...A.keys()].filter(k => !B.has(k));
  ok('DELETED a rebuild removes no item that ships today',
    deleted.length === 0,
    deleted.length ? `${deleted.length} gone: ${deleted.slice(0, 8).join(', ')}` : `${A.size} items all survive`);

  const changed = [...A.keys()].filter(k => B.has(k)
    && (A.get(k).name !== B.get(k).name || A.get(k).rarity !== B.get(k).rarity));
  const RANK = ['common', 'uncommon', 'rare', 'epic', 'legendary'];
  const demoted = changed.filter(k => RANK.indexOf(B.get(k).rarity) < RANK.indexOf(A.get(k).rarity));
  ok('CHANGED a rebuild renames nothing and re-rarities nothing',
    changed.length === 0,
    changed.length
      ? `${changed.length} changed, ${demoted.length} DEMOTED: ` + changed.slice(0, 5).map(k =>
        `${k} ${A.get(k).rarity}/"${A.get(k).name}" -> ${B.get(k).rarity}/"${B.get(k).name}"`).join(' | ')
      : `${A.size} items identical in name and rarity`);
}
fs.rmSync(tmp, { recursive: true, force: true });
console.log(`\n${fails ? `${fails} FAILED` : 'all green'}, 5 checks`);
process.exit(fails ? 1 : 0);
